<?php
namespace App\Exports;
use Maatwebsite\Excel\Concerns\FromArray; use Maatwebsite\Excel\Concerns\WithHeadings;
final class RosterScheduleImportFailuresExport implements FromArray, WithHeadings { public function __construct(private array $rows){} public function headings():array{return ['No','Baris Excel','NIK','Nomor KTP','Nama Excel','Nama HRIS','Tahun','Periode','Kolom','Nilai Bermasalah','Jenis Kegagalan','Alasan','Saran Perbaikan'];} public function array():array{return array_map(function($r,$i){$e=$r['errors'][0]??[];return [$i+1,$r['row_number'],$this->safe($r['nik']),$this->safe($r['no_ktp']),$this->safe($r['employee_name']),$this->safe($r['hris_name']),$r['year'],$r['period_number'],$e['column']??null,$this->safe($r['off_start']),$e['code']??null,$this->safe($e['reason']??null),'Perbaiki data lalu unggah kembali'];},$this->rows,array_keys($this->rows));} private function safe($v){return is_string($v)&&preg_match('/^[=+\-@]/',$v)?"'".$v:$v;} }
